const events:string[]=[];const inner:any={i:0,[Symbol.iterator](){return this;},next(){events.push("inner-next");this.i++;return {value:this.i,done:this.i>2};},return(){events.push("inner-close");return {done:true};}};const outer:any={i:0,[Symbol.iterator](){return this;},next(){events.push("outer-next");this.i++;return {value:inner,done:this.i>1};},return(){events.push("outer-close");return {done:true};}};const [[a]]=outer;console.log(a,events.join(","));
